import icontract


@icontract.require(lambda oldChar, newChar: len(oldChar) == 1 and len(newChar) == 1)
@icontract.ensure(lambda s, oldChar, newChar, result: len(result) == len(s) and all(
    (result[i] == newChar if s[i] == oldChar else result[i] == s[i]) for i in range(len(s))))
def replaceChars(s: str, oldChar: str, newChar: str) -> str:
    out = []
    for c in s:
        if c == oldChar:
            out.append(newChar)
        else:
            out.append(c)
    return "".join(out)
